// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    address fakeToken;

    function setUp() public {
        fakeToken = address(new FakeToken());
        c = new PuttyV2("", 0, address(this));
    }

    // ERC-1271 wallet so the fuzzer-created orders verify without vm.sign
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }

    function testFuzz_property(
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiryOffset,
        uint256 nonce
    ) public {
        strike = bound(strike, 1, 1e30);
        premium = bound(premium, 0, 1e30);
        duration = bound(duration, 1, 9_999 days);
        expiryOffset = bound(expiryOffset, 1, 1_000 days);
        nonce = bound(nonce, 0, 1e18);

        address[] memory emptyAddrs = new address[](0);
        PuttyV2.ERC20Asset[] memory noErc20 = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory noErc721 = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(this),
            isCall: false,
            isLong: false,
            baseAsset: fakeToken,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + expiryOffset,
            nonce: nonce,
            whitelist: emptyAddrs,
            floorTokens: emptyAddrs,
            erc20Assets: noErc20,
            erc721Assets: noErc721
        });

        bytes memory emptySig = new bytes(0);
        uint256[] memory noFloorIds = new uint256[](0);

        vm.prank(address(0xb0b));
        uint256 positionId = c.fillOrder(order, emptySig, noFloorIds);

        // General rule: a position NFT minted by a successful fillOrder is owned,
        // so its tokenURI is queryable and equals baseURI ++ id.
        bool ok;
        string memory uri;
        try c.tokenURI(positionId) returns (string memory u) {
            ok = true;
            uri = u;
        } catch {
            ok = false;
        }

        assertTrue(ok && keccak256(bytes(uri)) == keccak256(bytes(string.concat("", _idStr(positionId)))));
    }

    function _idStr(uint256 v) internal pure returns (string memory) {
        if (v == 0) return "0";
        uint256 digits;
        uint256 t = v;
        while (t != 0) { digits++; t /= 10; }
        bytes memory b = new bytes(digits);
        while (v != 0) { digits--; b[digits] = bytes1(uint8(48 + v % 10)); v /= 10; }
        return string(b);
    }
}

contract FakeToken {
    // Silent no-op token: returns empty returndata, so SafeTransferLib's checks pass.
    fallback() external {}
}
